import{_ as o,o as r,c as a,a2 as t}from"./chunks/framework.lxr64Vqo.js";const m=JSON.parse('{"title":"Frequently Asked Questions (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1795114725000}'),s={name:"faq.md"};function i(n,e,d,l,h,c){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="frequently-asked-questions-faq" tabindex="-1">Frequently Asked Questions (FAQ) <a class="header-anchor" href="#frequently-asked-questions-faq" aria-label="Permalink to &quot;Frequently Asked Questions (FAQ)&quot;">​</a></h1><p>Find answers to common questions regarding NoxMedia setup, streaming protocols, and client compatibility.</p><hr><h3 id="does-noxmedia-download-whole-files-to-host-device-storage" tabindex="-1">Does NoxMedia download whole files to host device storage? <a class="header-anchor" href="#does-noxmedia-download-whole-files-to-host-device-storage" aria-label="Permalink to &quot;Does NoxMedia download whole files to host device storage?&quot;">​</a></h3><p><strong>No.</strong> NoxMedia functions as a real-time streaming bridge. When you initiate playback on Infuse, Vesper, or Nuvio, NoxMedia requests stream byte chunks directly from Telegram&#39;s servers and pipes them over HTTP directly to your player. Host device storage is not consumed by media files.</p><hr><h3 id="is-noxmedia-completely-free" tabindex="-1">Is NoxMedia completely free? <a class="header-anchor" href="#is-noxmedia-completely-free" aria-label="Permalink to &quot;Is NoxMedia completely free?&quot;">​</a></h3><p><strong>Yes.</strong> NoxMedia is free and open-source under the AGPLv3 / MIT licenses. There are no subscriptions, paywalls, or feature tiers.</p><hr><h3 id="can-i-stream-outside-my-home-wi-fi-network" tabindex="-1">Can I stream outside my home Wi-Fi network? <a class="header-anchor" href="#can-i-stream-outside-my-home-wi-fi-network" aria-label="Permalink to &quot;Can I stream outside my home Wi-Fi network?&quot;">​</a></h3><p><strong>Yes.</strong> There are multiple supported methods to access your server remotely:</p><ol><li><strong>Tailscale / WireGuard (Recommended)</strong>: Install Tailscale on your host device and your remote device (iPhone, laptop). You obtain a secure private mesh IP (e.g., <code>http://100.x.y.z:8096</code>).</li><li><strong>Cloudflare Tunnels</strong>: Route port 8096 through a Cloudflare tunnel to your personal domain.</li><li><strong>Router Port Forwarding</strong>: Forward external port <code>8096</code> to your host device&#39;s local IP address in router administration.</li></ol><hr><h3 id="why-does-infuse-show-an-indexing-error-in-library-mode" tabindex="-1">Why does Infuse show an indexing error in Library Mode? <a class="header-anchor" href="#why-does-infuse-show-an-indexing-error-in-library-mode" aria-label="Permalink to &quot;Why does Infuse show an indexing error in Library Mode?&quot;">​</a></h3><p>In Infuse Settings -&gt; <strong>Library</strong>, do not enable full background library indexing on the NoxMedia share. Because Telegram channels often contain thousands of files, Infuse&#39;s recursive library crawler can exceed local network timeouts. Instead, browse through <strong>Files -&gt; NoxMedia</strong> (<strong>Direct Mode</strong>), which streams folder structures on-demand with zero-latency caching.</p><hr><h3 id="does-noxmedia-work-with-vesper" tabindex="-1">Does NoxMedia work with Vesper? <a class="header-anchor" href="#does-noxmedia-work-with-vesper" aria-label="Permalink to &quot;Does NoxMedia work with Vesper?&quot;">​</a></h3><p><strong>Yes.</strong> Vesper connects seamlessly using the Jellyfin server protocol (<code>http://&lt;HOST_IP&gt;:8096</code>), offering high-speed playback across macOS, iOS, iPadOS, and tvOS.</p><hr><h3 id="what-is-the-current-status-of-stremio-support" tabindex="-1">What is the current status of Stremio support? <a class="header-anchor" href="#what-is-the-current-status-of-stremio-support" aria-label="Permalink to &quot;What is the current status of Stremio support?&quot;">​</a></h3><p>Direct playback in Stremio is temporarily on hold while we resolve an issue related to Stremio&#39;s handling of localhost HTTP streaming endpoints on Android. In the interim, <strong>Nuvio</strong> is the officially recommended client for addon-based playback on Android, Windows, Mac, and Web.</p><hr><h3 id="what-video-and-audio-codecs-are-supported" tabindex="-1">What video and audio codecs are supported? <a class="header-anchor" href="#what-video-and-audio-codecs-are-supported" aria-label="Permalink to &quot;What video and audio codecs are supported?&quot;">​</a></h3><p>Because NoxMedia serves direct media streams, codec support is determined by your client player:</p><ul><li><strong>Infuse &amp; Vesper</strong>: Plays virtually all formats natively (4K HDR10, Dolby Vision, HEVC/H.265, AV1, DTS-HD MA, Dolby TrueHD Atmos, FLAC).</li><li><strong>Nuvio</strong>: Supports modern video formats via hardware decoders.</li><li><strong>Kodi</strong>: Plays all raw remuxes and multi-channel audio tracks.</li></ul>',25)])])}const p=o(s,[["render",i]]);export{m as __pageData,p as default};
